head.script:
scwin.onpageload = function() {
	window.dd = 0;
	if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
};
scwin.ibx_openPopup_onclick = function(e) {
	dd++
	if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
	var opts = {
		"id": "popup_wframe1" + dd,
		"type": "window",
		"width": "700px",
		"height": "250px",
		"top": 150,
		"left": 150,
		"popupName": "wframe_Popup1" + dd,
		modal: true,
		useModalStack: true,
		"useIFrame": true,
		"title": "focusTest",
		"alwaysOnTop": true,
		"frameMode": "wframe",
		useATagTitle: true,
		useATagBtn: true
	};
	$w.openPopup("/sample/common_link/gridView_senseReader_WEFF-579_(WSQ-3947)_sub2.xml", opts);
};
